        """Get all edge differences for edges within this clique and to previous clique"""
        diffs = []
        # Edges within clique
        for i1 in range(3):
            for i2 in range(i1+1, 3):
                d = abs(perm[i1] - perm[i2])
                diffs.append(d)
        # Edges to previous clique
        if clique_idx > 0:
            for i in range(3):
                d = abs(perm[i] - labels[3*(clique_idx-1)+i])
                diffs.append(d)
        return diffs

    def is_valid_clique(clique_idx, perm):
        """Check if assigning perm to this clique is valid"""
        # Check labels not used
        for p in perm:
            if p in used_labels:
                return False

        # Get all new edge differences
        new_diffs = get_all_new_diffs(clique_idx, perm)

        # Check no zero diffs
        for d in new_diffs:
            if d == 0:
                return False

        # Check no duplicates with existing diffs
        for d in new_diffs:
            if d in used_diffs:
                return False

        # Check no duplicates among new diffs
        if len(new_diffs) != len(set(new_diffs)):
            return False

        return True

    def assign_clique(clique_idx, perm):
        for i in range(3):
            v = 3*clique_idx + i
            labels[v] = perm[i]
            used_labels.add(perm[i])
        for d in get_all_new_diffs(clique_idx, perm):
            used_diffs.add(d)

    def unassign_clique(clique_idx, perm):
        for i in range(3):
            v = 3*clique_idx + i
            labels[v] = None
            used_labels.remove(perm[i])
        for d in get_all_new_diffs(clique_idx, perm):
            used_diffs.remove(d)

